package org.ruoyi.service.lawyer;
import org.junit.jupiter.api.*;import org.ruoyi.common.core.exception.ServiceException;import org.ruoyi.mapper.chat.ChatSessionMapper;import org.springframework.jdbc.core.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
@Tag("dev")class LawyerWorkTimeSecurityTest{
 @Test void foreignCaseCannotStartAnyTimer(){var jdbc=mock(JdbcTemplate.class);var cases=mock(CaseAccess.class);var sessions=mock(ChatSessionMapper.class);doThrow(new ServiceException("案件不可用",404)).when(cases).owned(99L,true);assertThrows(ServiceException.class,()->new LawyerWorkTimeService(jdbc,cases,sessions).start(99L,null,"测试"));verifyNoInteractions(jdbc);}
 @Test void foreignSessionIsRejectedBeforeInsert(){var jdbc=mock(JdbcTemplate.class);var cases=mock(CaseAccess.class);var sessions=mock(ChatSessionMapper.class);assertThrows(ServiceException.class,()->new LawyerWorkTimeService(jdbc,cases,sessions).start(null,99L,"测试"));verifyNoInteractions(jdbc,cases);}
 @Test void missingOrForeignStopUsesSameOwnerRestrictedQuery(){var jdbc=mock(JdbcTemplate.class);when(jdbc.query(anyString(),any(RowMapper.class),any(),any(),any())).thenReturn(List.of());var service=new LawyerWorkTimeService(jdbc,mock(CaseAccess.class),mock(ChatSessionMapper.class));var error=assertThrows(ServiceException.class,()->service.stop(99L));assertEquals(404,error.getCode());verify(jdbc).query(argThat(s->s.contains("tenant_id=? AND user_id=? FOR UPDATE")),any(RowMapper.class),eq(99L),any(),any());verify(jdbc,never()).update(anyString(),any(Object[].class));}
}
